12:   sentenceNumber: number;
13:   text: string;
14: }
15: 
16: /**
17:  * Checks whether a candidate sentence or text contains forbidden safety keywords
18:  * relating to edibility, toxicity, foraging, or medicinal ingestion.
19:  */
20: export function containsSafetyViolations(text: string): boolean {
21:   if (!text || typeof text !== 'string') return true;
22:   return EDIBILITY_SAFETY_REGEX.test(text);
23: }
24: 
25: /**
26:  * Strips any embedded citation brackets (e.g. "[1]", "(2)") from generated text
27:  * to ensure pure prose is stored and displayed cleanly.
28:  */
29: export function sanitizeFactText(text: string): string {
30:   return text
31:     .replace(/\[\d+\]/g, '')
32:     .replace(/\(\d+\)/g, '')
33:     .replace(/\s+/g, ' ')
34:     .trim();
35: }
36: 
37: /**
38:  * Filters a list of synthesized facts against safety rules and sentence index bounds.
39:  * Discards any fact that:
40:  * 1. References an out-of-bounds sentence number (< 1 or > maxSentenceIndex).
41:  * 2. Matches the edibility / toxic advice regex blacklist.
42:  * 3. Has an empty or overly short text body (< 5 characters).
43:  */
44: export function validateCitations(
45:   facts: FactItem[],
46:   maxSentenceIndex: number
47: ): FactItem[] {
48:   if (!Array.isArray(facts) || maxSentenceIndex < 1) return [];
49: 
50:   return facts
51:     .map((fact) => ({
52:       sentenceNumber: Number(fact.sentenceNumber),
53:       text: sanitizeFactText(fact.text),
54:     }))
55:     .filter((fact) => {
56:       // 1. Bounds check
57:       if (
58:         !Number.isInteger(fact.sentenceNumber) ||
59:         fact.sentenceNumber < 1 ||
60:         fact.sentenceNumber > maxSentenceIndex
61:       ) {
62:         return false;
63:       }
64: 
65:       // 2. Length check
66:       if (fact.text.length < 5) {
67:         return false;
68:       }
69: 
70:       // 3. Edibility / toxicity violation check
71:       if (containsSafetyViolations(fact.text)) {
72:         return false;
73:       }
74: 
75:       return true;
76:     });
