/**
 * Detects runaway degeneration, token repetition loops (e.g. pattern-pattern-pattern),
 * prompt template artifacts, or excessively long/corrupted text generated by small models.
 */
export function isGarbageOrDegenerate(text: string): boolean {
  if (!text || typeof text !== 'string') return true;
  const trimmed = text.trim();

  // 1. Minimum and maximum reasonable character length for a fact
  if (trimmed.length < 5 || trimmed.length > 220) return true;

  // 2. Word count limit (field notes should be max ~20-30 words)
  const words = trimmed.split(/\s+/).filter(Boolean);
  if (words.length > 35) return true;

  // 3. Repeated token / phrase loops (e.g., "pattern-pattern-pattern", "word word word word")
  if (/(\b[\w-]{2,}\b)(?:[- \t]+\1){2,}/i.test(trimmed)) return true;

  // 4. Runaway hyphenated or underscore chains inside any word
  if (words.some((w) => (w.match(/-/g) || []).length > 4 || (w.match(/_/g) || []).length > 3)) {
    return true;
  }

  // 5. Unnaturally long single token without spaces
  if (/\S{35,}/.test(trimmed)) return true;

  // 6. Common LLM prompt leak or tokenizer artifacts (e.g. ueff_exp, <eos>, [PAD])
  if (/ueff_|exp_\d|\[PAD\]|<eos>|<bos>|[\u0600-\u06FF]{2,}.*exp_/i.test(trimmed)) {
    return true;
  }

  return false;
}

/**
 * Filters a list of synthesized facts against safety rules and sentence index bounds.
 * Discards any fact that:
 * 1. References an out-of-bounds sentence number (< 1 or > maxSentenceIndex).
 * 2. Matches the edibility / toxic advice regex blacklist.
 * 3. Has an empty or overly short text body (< 5 characters) or is corrupted/degenerate.
 */
export function validateCitations(
  facts: FactItem[],
  maxSentenceIndex: number
): FactItem[] {
  if (!Array.isArray(facts) || maxSentenceIndex < 1) return [];

  return facts
    .map((fact) => ({
      sentenceNumber: Number(fact.sentenceNumber),
      text: sanitizeFactText(fact.text),
    }))
    .filter((fact) => {
      // 1. Bounds check
      if (
        !Number.isInteger(fact.sentenceNumber) ||
        fact.sentenceNumber < 1 ||
        fact.sentenceNumber > maxSentenceIndex
      ) {
        return false;
      }

      // 2. Length check
      if (fact.text.length < 5) {
        return false;
      }

      // 3. Edibility / toxicity violation check
      if (containsSafetyViolations(fact.text)) {
        return false;
      }

      // 4. Degeneration, token-loop, and garbage check
      if (isGarbageOrDegenerate(fact.text)) {
        return false;
      }

      return true;
    });
}

